package main

import "math"

// Functions are the six trial functions of Kron 1962, Fig. 3 (p. 56);
// "log" is base 10, as the given columns show.
var Functions = []func(x, y float64) float64{
	func(x, y float64) float64 { return 3*x + 4*y + 2 },
	func(x, y float64) float64 { return 5*x*y + 3*x + 4*y + 2 },
	func(x, y float64) float64 { return x*x + 2*y*y - 3*x*y + 5*x - 3*y + 6 },
	func(x, y float64) float64 { return x*x*x + 2*y*y*x - 2*x*x - 2*x*y + 4*y + 8 },
	func(x, y float64) float64 { return 10 * (1 + math.Log10(x+4) - 1/y) },
	func(x, y float64) float64 { return 10 * (2 + math.Exp(x/10) - y*math.Log10(x+10)) },
}

